REELS=[
R(id="r1",time="11:00",theme="dark",tag="BUYING PROCESS",area="BRAMPTON",fmt="step-by-step (moving in, supplementary tax bill on a new build)",aud="buyer",
 hook="Brampton new build. *Second tax bill?",kick="AFTER CLOSING",hprop="house",hsay="Brampton new build: second tax bill coming?",
 pts=[("Land-only bill","house","Early tax bills on a new build may reflect only the vacant land.","First, early tax bills on a new build may reflect only the vacant land."),
      ("MPAC reassesses","search","After you move in, MPAC values the finished home and sends a notice.","Next, after you move in, MPAC values the finished home and sends you a notice."),
      ("Bill reaches back","calendar","The new bill can go back to your closing or occupancy date.","Now the twist. Then, the new bill can go back to your closing or occupancy date."),
      ("Budget for it","calculator","It's a separate bill. Set money aside for it.","Finally, it's a separate bill, so set some money aside for it.","Timing and instalments vary by city. Sources: City of Brampton, Milton, Mississauga.")],
 cta="Like, comment and *share with a new-build buyer",csay="Like, comment and share this with someone closing on a new build. "+CTAW,
 fine=GEN,
 cap="Brampton new build. Second tax bill?\n\nWhen you buy a newly built home, a supplementary tax bill may follow after you move in. 1) Early tax bills on a new build may reflect only the vacant land. 2) After you move in, MPAC values the finished home and sends a Property Assessment Change Notice. 3) The City of Brampton says a new house is often assessed from the occupancy or closing date; the City of Mississauga says the bill can cover the current and up to two previous years, prorated from the effective date. 4) It is a separate bill that does not replace your regular bills, so budget for it. If your mortgage payment includes taxes, the bill may go to your lender. Instalments and due dates vary by municipality: check your own bill and the Property Assessment Change Notice.\nSources: City of Brampton, \"Supplementary Tax Bill\" (brampton.ca); Town of Milton, \"Assessments\" (milton.ca); City of Mississauga, \"Supplementary tax bill\" (mississauga.ca, page dated Jul 14, 2025), all checked Nov 24, 2026.\n\n"+CHK_B+"\n\n"+GEN,
 tags="#bramptonrealestate #peelregion #newbuild #keyswithkrishna",
 pattern="2 cost of a mistake + 6 tease",trigger="surprise at a bill nobody mentioned",share="a friend closing on a new build"),
R(id="r2",time="15:00",theme="cream",tag="SELLER TIPS",area="OAKVILLE",fmt="step-by-step (seller, CRA 365-day flipping rule)",aud="seller",trial=True,
 hook="Sell within a year? *Fully taxable.",kick="365-DAY RULE",hprop="calendar",hsay="Oakville seller: selling within a year, fully taxable?",
 pts=[("365-day test","calendar","Owned under 365 days in a row? The CRA may call it flipped.","First, own a home for less than three hundred sixty-five days in a row, and the CRA may call it flipped."),
      ("Fully taxable","calculator","The profit is taxed as business income. No principal residence exemption.","Now the twist. Next, that profit is taxed as business income, and the principal residence exemption doesn't apply."),
      ("Life exceptions","clipboard","Some life events are exceptions: a death, new child, separation or job loss.","Then, some life events are exceptions, like a death, a new child, a separation or a job loss."),
      ("Ask first","lawyer","Talk to a tax professional before you list.","Finally, talk to a tax professional before you list, because your own situation decides.","Rule applies from Jan 1, 2023. Source: Canada Revenue Agency.")],
 cta="Like, comment and *share with an Oakville seller",csay="Like, comment and share this with someone selling in Oakville. "+CTAW,
 fine=GENT,
 cap="Sell within a year? Fully taxable.\n\nThe Canada Revenue Agency's residential property flipping rule has applied since January 1, 2023. 1) A home owned for less than 365 consecutive days before it is sold is generally treated as a flipped property. 2) The profit is fully taxable as business income and does not qualify for the principal residence exemption or the 50 per cent capital gains inclusion rate. 3) Exceptions can apply for certain life events, such as a death, a household change like a new child, a separation, a safety threat, serious illness or disability, an involuntary job loss, a work or study relocation, insolvency or the loss of the property. 4) Your own situation decides, so talk to a tax professional before you list.\nSource: Canada Revenue Agency, \"Residential property flipping rule\" (canada.ca, page modified Oct 21, 2024), checked Nov 24, 2026.\n\nSelling in Oakville? "+CHK_S+"\n\n"+GENT,
 tags="#oakvillerealestate #haltonregion #sellingyourhome #keyswithkrishna",
 pattern="2 cost of a mistake",trigger="worry about an unexpected tax bill",share="a friend who may sell soon"),
R(id="r3",time="19:00",theme="dark",tag="MONEY MATH",area="MILTON",fmt="money-math (everyday, mortgage insurance premium on a $700K home)",aud="buyer",series="money-math",math="everyday",
 hook="$700K, low down payment. *Hidden cost?",kick="INSURANCE PREMIUM",hprop="calculator",hsay="Milton buyers: low down payment, hidden cost?",
 calc=[("Minimum down payment, $700K home","$45,000","$500K x 5% + $200K x 10%","$45,000 down","piggy","First, on a seven hundred thousand dollar home, the minimum down payment is forty-five thousand dollars."),
       ("Mortgage you need","$655,000","$700,000 - $45,000","$655,000 mortgage","house","Next, that leaves a six hundred fifty-five thousand dollar mortgage."),
       ("Mortgage insurance premium: 4.00%","$26,200","$655,000 x 4.00%","$26,200 added to mortgage","shield","Now the twist. Then, with under twenty percent down, mortgage insurance adds four percent: twenty-six thousand, two hundred dollars.")],
 total=("Mortgage you actually carry","$681,200","$655,000 + $26,200. Plus about $2,096 Ontario sales tax on the premium, due at closing.","Example only: $700K home; minimum down payment per FCAC (5% of the first $500,000 + 10% of the rest, up to $1.5M). CMHC premium table: 4.00% for 90.01% to 95% loan-to-value (here 93.6%). The premium may be added to the mortgage; Ontario sales tax (8%) on it cannot, so it is paid at closing. Lenders and insurers set final terms. Not mortgage, tax or legal advice.","Finally, that's a six hundred eighty-one thousand, two hundred dollar mortgage, plus about two thousand ninety-six dollars in sales tax at closing."),
 cta="Like, comment and *share with a Milton buyer",csay="Like, comment and share this with a Milton buyer. "+CTAW,
 fine="Example only. Not mortgage, tax or legal advice.",
 cap="$700K, low down payment. Hidden cost?\n\nExample only, for a $700,000 home with the minimum down payment:\n1) Minimum down payment: 5% of the first $500,000 + 10% of the other $200,000 = $45,000.\n2) Mortgage needed: $700,000 - $45,000 = $655,000.\n3) That is 93.6% of the price. CMHC's premium for 90.01% to 95% loan-to-value is 4.00%: $655,000 x 4.00% = $26,200, which may be added to the mortgage.\n4) Mortgage you carry: $655,000 + $26,200 = $681,200.\nOntario sales tax (8% of the premium, about $2,096) cannot be added to the mortgage and is paid at closing. Sagen and Canada Guaranty also insure mortgages, and each sets its own premiums. Closing costs are extra, and lenders and insurers set the final terms, so confirm your numbers with your lender.\n\nPlanning a move in Milton? "+INFO+"\n\nExample only. Not mortgage, tax or legal advice.\nSources: CMHC, \"CMHC Mortgage Loan Insurance cost\" (cmhc-schl.gc.ca); Financial Consumer Agency of Canada, \"How much you need for a down payment\" (canada.ca, page updated Oct 15, 2025); Ontario Ministry of Finance, Retail Sales Tax guide, insurance (ontario.ca, 8% rate), checked Nov 23-24, 2026.",
 tags="#miltonontario #haltonregion #mortgagetips #keyswithkrishna",
 pattern="2 cost of a mistake + 4 direct address",trigger="surprise at a cost nobody mentions",share="a friend buying with a small down payment"),
R(id="r4",time="20:00",theme="cream",tag="BUYING PROCESS",area="ETOBICOKE",fmt="step-by-step (new build, first-time buyers GST/HST rebate)",aud="buyer",
 hook="New build. *$50,000 rebate. Eligible?",kick="FIRST-TIME BUYERS",hprop="piggy",hsay="Etobicoke new build: fifty thousand dollar rebate, eligible?",
 pts=[("First-time test","clipboard","Be 18+, a citizen or PR, with no owned home lived in recently.","First, you must be eighteen or older, a citizen or permanent resident, and not recently have lived in a home you owned.","CRA test: current and previous four calendar years. Must be your primary residence."),
      ("Date and price","calendar","Agreement signed on or after Mar 20, 2025. Up to $50,000 back at $1M or less.","Next, your agreement has to be signed on or after March twentieth, twenty twenty-five, and a home at or under one million can get the full rebate."),
      ("Price cliff","chart","From $1M to $1.5M the rebate shrinks. At $1.5M or more, none.","Now the twist. Then, between one million and one point five million the rebate shrinks, and at one point five million there's none."),
      ("Sign the forms","lawyer","Your builder usually files it. Ask your lawyer which forms you sign.","Finally, your builder usually files it, so ask your lawyer which forms you sign at closing.","Federal GST/HST rebate. Ontario has a separate rebate. Source: Canada Revenue Agency.")],
 cta="Like, comment and *share with a first-time buyer",csay="Like, comment and share this with a first-time buyer. "+CTAW,
 fine="Eligibility rules apply. "+GENT,
 cap="New build. $50,000 rebate. Eligible?\n\nThe Canada Revenue Agency's first-time home buyers' GST/HST rebate covers newly built or substantially renovated homes. 1) You must be 18 or older, a Canadian citizen or permanent resident, and a first-time buyer under the CRA's test (not having lived in a home you or your spouse owned in the current or previous four calendar years). The home must be your primary residence. 2) The agreement of purchase and sale must be signed on or after March 20, 2025 (and before 2031). At or below $1 million the rebate is up to 100% of the GST (or federal part of the HST), to a maximum of $50,000. 3) Between $1 million and $1.5 million the maximum is gradually reduced; at $1.5 million or more there is no rebate. 4) With a builder purchase, the builder usually files, and the forms (GST190 and RC7190-ON) are signed with the builder or your lawyer around closing. Ontario has a separate first-time buyer rebate on the provincial part of the HST: see the CRA page for details. Eligibility rules apply.\nSource: Canada Revenue Agency, \"First-time home buyers' (FTHB) GST/HST rebate\" (canada.ca, pages modified Mar to Oct 2026), checked Nov 24, 2026.\n\nBuying new in Etobicoke? "+INFO+"\n\n"+GENT,
 tags="#etobicokerealestate #firsttimehomebuyer #newbuild #keyswithkrishna",
 pattern="11 interactive question + 3 sourced number",trigger="hope of a big rebate, fear of missing eligibility",share="a first-time buyer eyeing a new build"),
R(id="r5",time="21:00",theme="dark",tag="MYTH VS FACT",area="KITCHENER",fmt="myth vs fact (new condo 10-day cooling-off)",aud="buyer",
 hook="Kitchener condo signed. Missed *10 days?",kick="COOLING-OFF",hprop="calendar",hsay="Kitchener new condo: did you miss ten days?",
 pts=[("The myth","lawyer","Myth: once you sign for a new condo, you're locked in.","First, here's the myth: once you sign for a new condo, you're locked in."),
      ("Fact: 10 days","calendar","Fact: Ontario gives new-condo buyers a 10-day cooling-off period.","Now the twist. Next, Ontario gives new condo buyers a ten-day cooling-off period to cancel."),
      ("Clock starts","clipboard","It starts once you have the agreement, disclosure documents and Condo Guide.","Then, the clock starts once you've received the agreement, the disclosure documents and the Condo Guide."),
      ("Use the time","search","Review the documents with your lawyer inside that window.","Finally, review everything with your lawyer inside that window.","Condo Act s.73(2). Source: Tarion. Applies to new condo purchases.")],
 cta="Like, comment and *share with a condo buyer",csay="Like, comment and share this with someone buying a new condo. "+CTAW,
 fine=GEN,
 cap="Kitchener condo signed. Missed 10 days?\n\nMyth: once you sign for a new condo, you are locked in. Fact: under section 73(2) of Ontario's Condominium Act, buyers of a new condo have a 10-day cooling-off period in which they may rescind their agreement of purchase and sale. Tarion says the period begins on the later of the date you receive the agreement of purchase and sale, the disclosure documents and the Condo Guide. Use that window to review everything with your lawyer, because after it ends you may no longer be able to rescind. This applies to new condo purchases from a developer, not resale condos.\nSource: Tarion, \"Building and selling condominiums\" (tarion.com), checked Nov 24, 2026.\n\nBuying a condo in Kitchener-Waterloo? "+INFO+"\n\n"+GEN,
 tags="#kitchenerwaterloo #condobuyers #homebuyingtips #keyswithkrishna",
 pattern="1 contrarian / myth + 7 scene",trigger="relief that there is still time",share="a friend who just signed for a condo"),
R(id="r6",time="22:30",theme="cream",tag="QUICK TIP",area="GEORGETOWN",fmt="quick-tip (vermiculite attic insulation)",aud="buyer",
 hook="Old attic insulation. *Asbestos risk?",kick="VERMICULITE",hprop="house",hsay="Georgetown older home: could attic insulation hold asbestos?",
 pts=[("Attic insulation","house","Some vermiculite attic insulation may contain asbestos. Don't disturb it.","Quick tip: some vermiculite attic insulation may contain asbestos, so ask your inspector about it and don't disturb it.","Source: Health Canada.")],
 cta="Like, comment and *share with an older-home buyer",csay="Like, comment and share this with someone buying an older home. "+CTAW,
 fine=GEN,
 cap="Old attic insulation. Asbestos risk?\n\nQuick tip: Health Canada says some vermiculite insulation may contain asbestos. If a home you are buying has it in the attic or walls, the guidance is to leave it undisturbed, not use the attic for storage, not try to remove it yourself, and hire professionals trained to handle asbestos before any renovation. Ask your home inspector to flag attic insulation, and talk to your Realtor® about what to ask the seller.\nSource: Health Canada, \"Asbestos and your health\" (canada.ca, page modified Feb 10, 2023), and Employment and Social Development Canada, \"Vermiculite Insulation Containing Tremolite Asbestos\" (canada.ca), checked Nov 24, 2026.\n\nBuying an older home in Georgetown? "+INFO+"\n\n"+GEN,
 tags="#georgetownontario #haltonhills #homeinspection #keyswithkrishna",
 pattern="4 direct address with a stake",trigger="worry about a hidden health hazard",share="a friend eyeing an older home"),
]
